global.schema:
type FieldLogState {
  observations: [Observation!]!
}

type Observation {
  id: ID!
  note: String!
  recordedBy: String!
}

operations.schema:
input LogObservationInput {
  id: ID!
  note: String!
}

operations.reducer:
if (state.observations.some((observation) => observation.id === action.input.id)) {
  throw new DuplicateObservationError(`Observation ${action.input.id} already exists`);
}
state.observations.push({
  id: action.input.id,
  note: action.input.note,
  recordedBy: action.context?.signer?.user?.address ?? "anonymous",
});
